begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_development_dimensions(id uuid primary key default gen_random_uuid(),dimension_key text unique not null,name_fr text not null,description_fr text,sort_order int not null default 0,status text not null default 'active' check(status in('active','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_development_categories(id uuid primary key default gen_random_uuid(),category_key text unique not null,name_fr text not null,description_fr text,age_min_months int,age_max_months int,dimension_id uuid references public.angelcare_marketplace_development_dimensions(id),sort_order int not null default 0,status text not null default 'draft' check(status in('draft','review','approved','published','suspended','archived')),owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(age_min_months is null or age_min_months>=0),check(age_max_months is null or age_max_months>=coalesce(age_min_months,0)));
create table if not exists public.angelcare_marketplace_development_activities(id uuid primary key default gen_random_uuid(),activity_key text unique not null,category_id uuid references public.angelcare_marketplace_development_categories(id),title_fr text not null,objective_fr text not null,age_min_months int,age_max_months int,duration_minutes int,difficulty text not null default 'foundation' check(difficulty in('foundation','progressive','advanced')),materials text[] not null default '{}',safety_notes_fr text,contraindications_fr text,source_locale text not null default 'fr' check(source_locale='fr'),status text not null default 'draft' check(status in('draft','review','approved','published','suspended','archived')),territory_id uuid,owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_development_activity_steps(id uuid primary key default gen_random_uuid(),activity_id uuid not null references public.angelcare_marketplace_development_activities(id) on delete cascade,step_order int not null,instruction_fr text not null,duration_minutes int,safety_checkpoint boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(activity_id,step_order));
create table if not exists public.angelcare_marketplace_development_kits(id uuid primary key default gen_random_uuid(),kit_key text unique not null,name_fr text not null,description_fr text,kit_type text not null default 'starter' check(kit_type in('starter','thematic','professional','institutional')),age_min_months int,age_max_months int,status text not null default 'draft' check(status in('draft','review','approved','published','suspended','archived')),territory_id uuid,owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_development_kit_items(id uuid primary key default gen_random_uuid(),kit_id uuid not null references public.angelcare_marketplace_development_kits(id) on delete cascade,item_key text not null,item_name_fr text not null,quantity numeric(12,2) not null default 1,unit text not null default 'piece',mandatory boolean not null default true,alternative_group text,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(kit_id,item_key));
create table if not exists public.angelcare_marketplace_development_guides(id uuid primary key default gen_random_uuid(),guide_key text unique not null,title_fr text not null,guide_type text not null check(guide_type in('activity','kit','category','safety','caregiver')),object_id uuid,content_fr jsonb not null default '{}',status text not null default 'draft' check(status in('draft','review','approved','published','archived')),version int not null default 1,owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_development_alternatives(id uuid primary key default gen_random_uuid(),object_type text not null check(object_type in('activity','kit','material')),object_id uuid not null,alternative_object_type text not null,alternative_object_id uuid,alternative_label_fr text not null,reason_fr text not null,priority int not null default 0,status text not null default 'active' check(status in('active','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_development_supplier_specs(id uuid primary key default gen_random_uuid(),spec_key text unique not null,title_fr text not null,object_type text not null check(object_type in('activity','kit','material')),object_id uuid,mandatory_requirements text[] not null default '{}',quality_requirements text[] not null default '{}',prohibited_materials text[] not null default '{}',evidence_requirements text[] not null default '{}',status text not null default 'draft' check(status in('draft','review','approved','published','suspended','archived')),owner_id uuid,reviewer_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists angelcare_dev_activities_status_idx on public.angelcare_marketplace_development_activities(status,category_id,updated_at desc);
create index if not exists angelcare_dev_kits_status_idx on public.angelcare_marketplace_development_kits(status,updated_at desc);
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.development.view','Voir le moteur Développement enfant','Développement & Montessori',false),('marketplace.development.manage','Gérer les activités','Développement & Montessori',true),('marketplace.development.publish','Publier les activités','Développement & Montessori',true),('marketplace.development.kits.view','Voir les kits','Développement & Montessori',false),('marketplace.development.kits.manage','Gérer les kits','Développement & Montessori',true),('marketplace.development.supplier_specs.view','Voir les spécifications fournisseurs','Développement & Montessori',false),('marketplace.development.supplier_specs.manage','Gérer les spécifications fournisseurs','Développement & Montessori',true),('marketplace.development.export','Exporter les preuves Développement','Développement & Montessori',true)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.development.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/development',required_permissions=array['marketplace.development.view']::text[],version=version+1,updated_at=now() where module_key='marketplace.child-development' or introduced_by_mega_zip=8;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.child-development.enabled','Développement enfant & kits','Activités, Montessori, kits, guides, alternatives et spécifications.',true,'active','Ultra Delivery 2/5') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_development_dimensions enable row level security;alter table public.angelcare_marketplace_development_categories enable row level security;alter table public.angelcare_marketplace_development_activities enable row level security;alter table public.angelcare_marketplace_development_activity_steps enable row level security;alter table public.angelcare_marketplace_development_kits enable row level security;alter table public.angelcare_marketplace_development_kit_items enable row level security;alter table public.angelcare_marketplace_development_guides enable row level security;alter table public.angelcare_marketplace_development_alternatives enable row level security;alter table public.angelcare_marketplace_development_supplier_specs enable row level security;
revoke all on table public.angelcare_marketplace_development_dimensions,public.angelcare_marketplace_development_categories,public.angelcare_marketplace_development_activities,public.angelcare_marketplace_development_activity_steps,public.angelcare_marketplace_development_kits,public.angelcare_marketplace_development_kit_items,public.angelcare_marketplace_development_guides,public.angelcare_marketplace_development_alternatives,public.angelcare_marketplace_development_supplier_specs from anon,authenticated;
grant all on table public.angelcare_marketplace_development_dimensions,public.angelcare_marketplace_development_categories,public.angelcare_marketplace_development_activities,public.angelcare_marketplace_development_activity_steps,public.angelcare_marketplace_development_kits,public.angelcare_marketplace_development_kit_items,public.angelcare_marketplace_development_guides,public.angelcare_marketplace_development_alternatives,public.angelcare_marketplace_development_supplier_specs to service_role;
commit;
